<style>
.dmz{position:relative;display:block;text-decoration:none;overflow:hidden}
.dmw{container:dm/inline-size;position:absolute;inset:0}
.dm{position:relative;display:block;overflow:hidden;width:100%;height:100%;color:#0B2A5B;text-decoration:none;font-family:'Bornomala',Inter,system-ui,sans-serif;background:linear-gradient(180deg,#3DA8F4 0%,#7CC8F8 52%,#CFEBFF 100%)}
.dm,.dm *{box-sizing:border-box}
.dm .rays{position:absolute;inset:-30% -10%;background:repeating-conic-gradient(from 0deg at 70% 48%,rgba(255,255,255,.2) 0 5deg,rgba(255,255,255,0) 5deg 10deg);-webkit-mask-image:radial-gradient(circle at 70% 48%,#000 0,transparent 68%);mask-image:radial-gradient(circle at 70% 48%,#000 0,transparent 68%);animation:dmSpin 90s linear infinite}
@keyframes dmSpin{to{transform:rotate(360deg)}}
.dm .cl{position:absolute;border-radius:50%;background:#fff;filter:blur(1.2cqw);opacity:.75;animation:dmDrift 46s linear infinite}
.dm .cl.a{width:15cqw;height:4.2cqw;left:-14cqw;top:4cqw}
.dm .cl.b{width:11cqw;height:3.2cqw;left:-12cqw;top:30cqw;animation-duration:62s;animation-delay:-20s;opacity:.55}
.dm .cl.c{width:13cqw;height:3.6cqw;left:-14cqw;top:14cqw;animation-duration:74s;animation-delay:-45s;opacity:.5}
@keyframes dmDrift{to{transform:translateX(125cqw)}}
.dm .logo{position:absolute;left:3.2cqw;top:2.2cqw;width:16cqw;height:auto;display:block}
.dmz .dm img.logo{width:16cqw;height:auto;object-fit:contain}
.dm .tag{position:absolute;left:3.2cqw;top:8.3cqw;width:16cqw;display:flex;align-items:center;gap:.6cqw;font-size:max(8px,1.05cqw);font-weight:500;color:#0B2A5B;white-space:nowrap}
.dm .tag:before,.dm .tag:after{content:"";height:1px;flex:1;background:rgba(11,42,91,.35)}
.dm .bd{position:absolute;width:6.8cqw;height:6.8cqw;border-radius:50%;background:#fff;border:.35cqw solid #FF6A00;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;font:700 max(7px,.95cqw)/1.15 Inter,system-ui,sans-serif;letter-spacing:.02em;color:#0B2A5B;box-shadow:0 .8cqw 1.8cqw rgba(11,42,91,.18)}
.dm .bd b{font-size:max(8px,1.3cqw);color:#FF6A00;display:block}
.dm .bd.a{left:4.6cqw;top:15cqw}.dm .bd.b{left:12.2cqw;top:18.6cqw;border-color:#16A34A}.dm .bd.b b{color:#16A34A}
