.dm .route circle{fill:#FF6A00;stroke:#fff;stroke-width:1.6}
.dm .h{position:absolute;left:24.5cqw;top:2.4cqw;width:41cqw;display:flex;flex-direction:column}
.dm .h1{font-size:5.4cqw;line-height:1.12;font-weight:700;background:linear-gradient(95deg,#E6197A 0%,#FF4D2E 60%,#FF7A00 100%);-webkit-background-clip:text;background-clip:text;color:transparent;-webkit-text-stroke:0;filter:drop-shadow(0 .25cqw 0 #fff) drop-shadow(0 .5cqw .8cqw rgba(11,42,91,.18))}
.dm .h2{font-size:5cqw;line-height:1.12;font-weight:700;color:#0B3D91;text-shadow:0 .25cqw 0 #fff,0 0 .3cqw #fff,0 .5cqw .8cqw rgba(11,42,91,.18)}
.dm .chips{position:absolute;left:24.5cqw;top:17.2cqw;height:3.3cqw;padding:0 2cqw;display:flex;align-items:center;gap:1.1cqw;background:#fff;border-radius:99cqw;font-size:max(10px,1.5cqw);font-weight:700;color:#0B3D91;box-shadow:0 .6cqw 1.6cqw rgba(11,42,91,.14);white-space:nowrap}
.dm .chips i{width:.5cqw;height:.5cqw;min-width:3px;min-height:3px;border-radius:50%;background:#FF6A00;display:block}
.dm .tk{position:absolute;left:24.5cqw;top:21.6cqw;width:40cqw;height:5.8cqw;padding:0 1.6cqw;display:flex;align-items:center;gap:1.4cqw;background:rgba(255,255,255,.94);border-radius:1.4cqw;box-shadow:0 .8cqw 2cqw rgba(11,42,91,.16)}
.dm .tk .sw{flex:none;width:3.2cqw;height:3.2cqw;border-radius:50%;background:var(--c,#D1D5DB);box-shadow:0 0 0 .5cqw color-mix(in srgb,var(--c,#D1D5DB) 28%,transparent);transition:background .25s,box-shadow .25s}
.dm .tk .tx{min-width:0;flex:1}
.dm .tk .nm{font-size:max(13px,2.3cqw);line-height:1.1;font-weight:700;color:#0B2A5B;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm .tk .sb{font-size:max(9px,1.2cqw);line-height:1.35;font-weight:500;color:#4B5563;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm .tk .dct{flex:none;white-space:nowrap;text-align:right;font-weight:700;color:#0B3D91;font-size:max(11px,1.7cqw);line-height:1.1}
.dm .tk .dct small{display:block;font-size:max(8px,.95cqw);font-weight:500;color:#6B7280}
.dm .tk .pb{position:absolute;left:1.6cqw;right:1.6cqw;bottom:.55cqw;height:.3cqw;border-radius:9cqw;background:rgba(11,61,145,.12);overflow:hidden}
.dm .tk .pb i{display:block;height:100%;width:0;background:linear-gradient(90deg,#E6197A,#FF7A00);transition:width .12s linear}
.dm .tk .sw.pop,.dm .tk .nm.pop,.dm .tk .sb.pop{animation:dmPop .3s ease-out}
@keyframes dmPop{from{opacity:.2;transform:translateY(.5cqw)}to{opacity:1;transform:none}}
.dm .ct2{position:absolute;left:24.5cqw;bottom:1.6cqw;height:3.2cqw;padding:0 1.8cqw;display:flex;align-items:center;gap:1.6cqw;background:#fff;border-radius:99cqw;font-size:max(10px,1.45cqw);font-weight:700;color:#0B2A5B;box-shadow:0 .6cqw 1.6cqw rgba(11,42,91,.14);white-space:nowrap}
.dm .ct2 svg{width:1.7cqw;height:1.7cqw;min-width:11px;min-height:11px;flex:none;color:#FF6A00}
.dm .ct2 s{width:1px;height:1.8cqw;background:#D1D5DB;text-decoration:none}
.dm .map{position:absolute;left:71cqw;top:1.1cqw;width:22cqw;height:auto;display:block;overflow:visible;filter:drop-shadow(0 1cqw 1.4cqw rgba(11,42,91,.22))}
.dm .map path{fill:rgba(255,255,255,.62);stroke:#fff;stroke-width:1.1;stroke-linejoin:round;transition:fill .4s ease,filter .4s ease}
.dm .map path.lit{fill:var(--c)}
.dm .map path.now{filter:brightness(1.12) saturate(1.2) drop-shadow(0 0 7px var(--c));stroke-width:1.8;transform-box:fill-box;transform-origin:center;animation:dmNow .55s cubic-bezier(.2,1.5,.4,1)}
@keyframes dmNow{0%{transform:scale(1)}45%{transform:scale(1.14)}100%{transform:scale(1)}}
.dm .map circle.rp{fill:none;stroke:var(--c);stroke-width:2;opacity:0;transform-box:fill-box;transform-origin:center}
.dm .map circle.rp.go{animation:dmRp .9s ease-out}
@keyframes dmRp{0%{opacity:.9;transform:scale(.3)}100%{opacity:0;transform:scale(3.2)}}
.dm.done .map path.lit{animation:dmAll 1.6s ease-in-out 1}
@keyframes dmAll{0%,100%{filter:none}50%{filter:brightness(1.18) saturate(1.2)}}
@media(prefers-reduced-motion:reduce){.dm .rays,.dm .cl,.dm .map path.now,.dm .map circle.rp.go,.dm.done .map path.lit{animation:none!important}}
@media(max-width:760px){.dmz{aspect-ratio:auto;display:flex}.dmw{position:relative;inset:auto;flex:1;display:flex;width:100%}.dm{height:auto;flex:1;justify-content:center}}
@container dm (max-width:760px){
.dm{display:flex;flex-direction:column;align-items:center;gap:3.4cqw;padding:5cqw 4cqw 5cqw}
.dm .logo,.dm .tag,.dm .bd,.dm .route,.dm .h,.dm .chips,.dm .tk,.dm .ct2,.dm .map{position:relative;left:auto;top:auto;bottom:auto;right:auto}
.dm .logo{order:1}.dmz .dm img.logo{width:34cqw}
.dm .tag{display:none}.dm .bd,.dm .route{display:none}
.dm .h{order:2;width:100%;align-items:center;text-align:center}
.dm .h1{font-size:11.5cqw}.dm .h2{font-size:10.5cqw}
.dm .map{order:3;width:62cqw}
.dm .tk{order:4;width:100%;height:15cqw;padding:0 3.4cqw;gap:3cqw;border-radius:3cqw}
.dm .tk .sw{width:7cqw;height:7cqw}
.dm .tk .nm{font-size:5.6cqw}.dm .tk .sb{font-size:3cqw}.dm .tk .dct{font-size:4.2cqw}.dm .tk .dct small{font-size:2.6cqw}
.dm .tk .pb{left:3.4cqw;right:3.4cqw;bottom:1.2cqw;height:.8cqw}
.dm .chips{order:5;height:8cqw;padding:0 4.6cqw;gap:2.4cqw;font-size:3.5cqw}.dm .chips i{width:1.2cqw;height:1.2cqw}
.dm .ct2{order:6;height:8cqw;padding:0 4cqw;gap:3cqw;font-size:3.5cqw}.dm .ct2 svg{width:4cqw;height:4cqw}.dm .ct2 s{height:4cqw}
}
</style>
<div class="dmw"><div class="dm" id="dm">
