<script>
(function(){
var el=document.currentScript&&document.currentScript.parentNode;var root=document.getElementById('dm');if(!root)return;var DATA=null,ready=false,want=false;
function build(){var map=root.querySelector('.map'),NS='http://www.w3.org/2000/svg',paths=[],pins=[];
var bn=function(n){return String(n).replace(/\d/g,function(d){return '০১২৩৪৫৬৭৮৯'[d]})};
var HUE={'Dhaka':24,'Chattogram':142,'Khulna':276,'Mymensingh':332,'Rajshahi':214,'Rangpur':246,'Sylhet':2,'Barishal':174,'Barisal':174};
var ORDER=['Dhaka','Mymensingh','Sylhet','Chattogram','Barishal','Khulna','Rajshahi','Rangpur'];
var byDiv={};DATA.d.forEach(function(x){(byDiv[x.dv]=byDiv[x.dv]||[]).push(x)});
var seq=[];ORDER.forEach(function(k){(byDiv[k]||[]).forEach(function(x,i){x.col='hsl('+((HUE[k]||200)+(i%3-1)*7)+' 82% '+(50+(i%3-1)*5)+'%)';seq.push(x)})});
DATA.d.forEach(function(x){var p=document.createElementNS(NS,'path');p.setAttribute('d',x.d);p.style.setProperty('--c',x.col||'#9CA3AF');map.appendChild(p);paths[x.id]=p;});
DATA.d.forEach(function(x){var c=document.createElementNS(NS,'circle');c.setAttribute('class','rp');c.setAttribute('cx',x.cx);c.setAttribute('cy',x.cy);c.setAttribute('r',16);c.style.setProperty('--c',x.col||'#9CA3AF');map.appendChild(c);pins[x.id]=c;});
var tk=root.querySelector('.tk'),sw=tk.querySelector('.sw'),nm=tk.querySelector('.nm'),sb=tk.querySelector('.sb'),ct=tk.querySelector('.n'),pb=tk.querySelector('.pb i');
function pop(e){e.classList.remove('pop');void e.offsetWidth;e.classList.add('pop')}
var STEP=100,idx=0,timer=0,hold=0,prev=null,running=false;
function reset(){clearInterval(timer);clearTimeout(hold);idx=0;prev=null;root.classList.remove('done');paths.forEach(function(p){if(p){p.classList.remove('lit','now')}});pins.forEach(function(c){if(c)c.classList.remove('go')});nm.textContent='সারা বাংলাদেশে';sb.textContent='প্রতিটি জেলায় ক্যাশ অন ডেলিভারি';sw.style.removeProperty('--c');sw.style.background='';ct.textContent='০';pb.style.width='0'}
function finish(){root.classList.add('done');if(prev)prev.classList.remove('now');nm.textContent='৬৪ জেলাতেই ডেলিভারি';sb.textContent='ঘরে বসেই অর্ডার, দেশের যেকোনো প্রান্তে';sw.style.background='linear-gradient(135deg,#E6197A,#FF7A00)';pop(nm);pop(sb)}
function step(){
 if(idx>=seq.length){clearInterval(timer);finish();if(!root.hasAttribute('data-loop'))return;hold=setTimeout(function(){if(running){reset();timer=setInterval(step,STEP)}},3800);return}
 var x=seq[idx++],p=paths[x.id],c=pins[x.id];
 if(prev)prev.classList.remove('now');
 p.classList.add('lit','now');prev=p;
 c.classList.remove('go');void c.getBoundingClientRect();c.classList.add('go');
 sw.style.background=x.col;sw.style.setProperty('--c',x.col);nm.textContent=x.bn+' জেলা';sb.textContent=x.dvbn+' বিভাগ · ক্যাশ অন ডেলিভারি';ct.textContent=bn(idx);pb.style.width=(idx/seq.length*100)+'%';pop(nm);pop(sb);
}
function start(){if(running)return;running=true;if(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches){seq.forEach(function(x){paths[x.id].classList.add('lit')});idx=seq.length;ct.textContent=bn(64);pb.style.width='100%';finish();return}reset();timer=setInterval(step,STEP)}
function stop(){running=false;reset()}
root.__dm={start:start,stop:stop};ready=true;if(want)start()}
function load(){if(DATA||load.p)return;load.p=1;fetch('/bd64.json').then(function(r){return r.json()}).then(function(j){DATA=j;build()}).catch(function(){})}
var t=el&&el.closest('.sl-t'),raf=0;
function vis(){if(!t)return 1;var a=el.getBoundingClientRect(),b=t.getBoundingClientRect(),w=Math.min(a.right,b.right)-Math.max(a.left,b.left);return a.width?Math.max(0,w)/a.width:0}
function upd(){raf=0;var r=vis();if(r>=.5){want=true;if(ready)root.__dm.start()}else if(r<=.02){want=false;if(ready)root.__dm.stop()}}
function q(){if(!raf)raf=requestAnimationFrame(upd)}
if(t){t.addEventListener('scroll',q,{passive:true});addEventListener('resize',q)}
(window.requestIdleCallback||function(f){setTimeout(f,1200)})(function(){load();upd()});
})();
</script>
